using System.ComponentModel.Composition;
using XrmToolBox.Extensibility;
using XrmToolBox.Extensibility.Interfaces;

namespace XTB.StepManipulationTool
{
    [Export(typeof(IXrmToolBoxPlugin)),
    ExportMetadata("Name", "Steps Manipulator"),
    ExportMetadata("Description", "Move plugin steps between plugin types while preserving step GUIDs (Dataverse/Dynamics 365) for cleaner ALM changes"),
    ExportMetadata("AssemblyCompany", "Alexey Skytikov and Imran Akram"),
    ExportMetadata("SmallImageBase64", ""), // null for "no logo" image or base64 image content
    ExportMetadata("BigImageBase64", ""),
    ExportMetadata("BackgroundColor", "#ffffff"), // Use a HTML color name
    ExportMetadata("PrimaryFontColor", "#000000"), // Or an hexadecimal code
    ExportMetadata("SecondaryFontColor", "DarkGray")]
    public class PluginDescription : PluginBase
    {
        #region Public Methods

        public override IXrmToolBoxPluginControl GetControl()
        {
            return new MainControl();
        }

        #endregion Public Methods
    }
}